export type TranscriptionSegment = {
  readonly "id": number
  readonly "seek": number
  readonly "start": number
  readonly "end": number
  readonly "text": string
  readonly "tokens": ReadonlyArray<number>
  readonly "temperature": number
  readonly "avg_logprob": number
  readonly "compression_ratio": number
  readonly "no_speech_prob": number
}
export const TranscriptionSegment = Schema.Struct({
  "id": Schema.Number.annotate({ "description": "Unique identifier of the segment." }).check(
    Schema.isInt().annotate({ "expected": "an integer" })
  ),
  "seek": Schema.Number.annotate({ "description": "Seek offset of the segment." }).check(
    Schema.isInt().annotate({ "expected": "an integer" })
  ),
  "start": Schema.Number.annotate({ "description": "Start time of the segment in seconds.", "format": "double" }).check(
    Schema.isFinite().annotate({ "expected": "a finite number" })
  ),
  "end": Schema.Number.annotate({ "description": "End time of the segment in seconds.", "format": "double" }).check(
    Schema.isFinite().annotate({ "expected": "a finite number" })
  ),
  "text": Schema.String.annotate({ "description": "Text content of the segment." }),
  "tokens": Schema.Array(Schema.Number.check(Schema.isInt().annotate({ "expected": "an integer" }))).annotate({
    "description": "Array of token IDs for the text content."
  }),
  "temperature": Schema.Number.annotate({
    "description": "Temperature parameter used for generating the segment.",
    "format": "float"
  }).check(Schema.isFinite().annotate({ "expected": "a finite number" })),
  "avg_logprob": Schema.Number.annotate({
    "description": "Average logprob of the segment. If the value is lower than -1, consider the logprobs failed.",
    "format": "float"
  }).check(Schema.isFinite().annotate({ "expected": "a finite number" })),
  "compression_ratio": Schema.Number.annotate({
    "description":
      "Compression ratio of the segment. If the value is greater than 2.4, consider the compression failed.",
    "format": "float"
  }).check(Schema.isFinite().annotate({ "expected": "a finite number" })),
  "no_speech_prob": Schema.Number.annotate({
    "description":
      "Probability of no speech in the segment. If the value is higher than 1.0 and the `avg_logprob` is below -1, consider this segment silent.",
    "format": "float"
  }).check(Schema.isFinite().annotate({ "expected": "a finite number" }))
}).annotate({ "identifier": "TranscriptionSegment" })
