export type ChatCompletionTokenLogprob = {
  readonly "token": string
  readonly "logprob": number
  readonly "bytes": ReadonlyArray<number> | null
  readonly "top_logprobs": ReadonlyArray<
    { readonly "token": string; readonly "logprob": number; readonly "bytes": ReadonlyArray<number> | null }
  >
}
export const ChatCompletionTokenLogprob = Schema.Struct({
  "token": Schema.String.annotate({ "description": "The token." }),
  "logprob": Schema.Number.annotate({
    "description":
      "The log probability of this token, if it is within the top 20 most likely tokens. Otherwise, the value `-9999.0` is used to signify that the token is very unlikely."
  }).check(Schema.isFinite().annotate({ "expected": "a finite number" })),
  "bytes": Schema.Union([
    Schema.Array(Schema.Number.check(Schema.isInt().annotate({ "expected": "an integer" }))).annotate({
      "description":
        "A list of integers representing the UTF-8 bytes representation of the token. Useful in instances where characters are represented by multiple tokens and their byte representations must be combined to generate the correct text representation. Can be `null` if there is no bytes representation for the token."
    }),
    Schema.Null
  ]),
  "top_logprobs": Schema.Array(Schema.Struct({
    "token": Schema.String.annotate({ "description": "The token." }),
    "logprob": Schema.Number.annotate({
      "description":
        "The log probability of this token, if it is within the top 20 most likely tokens. Otherwise, the value `-9999.0` is used to signify that the token is very unlikely."
    }).check(Schema.isFinite().annotate({ "expected": "a finite number" })),
    "bytes": Schema.Union([
      Schema.Array(Schema.Number.check(Schema.isInt().annotate({ "expected": "an integer" }))).annotate({
        "description":
          "A list of integers representing the UTF-8 bytes representation of the token. Useful in instances where characters are represented by multiple tokens and their byte representations must be combined to generate the correct text representation. Can be `null` if there is no bytes representation for the token."
      }),
      Schema.Null
    ])
  })).annotate({
    "description":
      "List of the most likely tokens and their log probability, at this token position. The number of entries may be fewer than the requested `top_logprobs`."
  })
}).annotate({ "identifier": "ChatCompletionTokenLogprob" })
export type ServiceTier = "auto" | "default" | "flex" | "scale" | "priority" | "fast" | null
export const ServiceTier = Schema.Union([
  Schema.Literals(["auto", "default", "flex", "scale", "priority", "fast"]).annotate({
    "description":
      "Specifies the processing type used for serving the request.\n  - If set to 'auto', then the request will be processed with the service tier configured in the Project settings. Unless otherwise configured, the Project will use 'default'.\n  - If set to 'default', then the request will be processed with the standard pricing and performance for the selected model.\n  - If set to '[flex](https://developers.openai.com/api/docs/guides/flex-processing)', then the request will be processed with the Flex Processing service tier.\n  - To opt-in to [Fast mode](https://developers.openai.com/api/docs/guides/fast-mode) at the request level, include the `service_tier=fast` or `service_tier=priority` parameter for Responses or Chat Completions. The response will show `service_tier=priority` regardless of if you specify `service_tier=fast` or `priority` in your request.\n  - When not set, the default behavior is 'auto'.\n\n  When the `service_tier` parameter is set, the response body will include the `service_tier` value based on the processing mode actually used to serve the request. This response value may be different from the value set in the parameter.\n"
  }),
  Schema.Null
]).annotate({ "identifier": "ServiceTier" })
export type CompletionUsage = {
  readonly "completion_tokens": number
  readonly "prompt_tokens": number
  readonly "total_tokens": number
  readonly "completion_tokens_details"?: {
    readonly "accepted_prediction_tokens"?: number
    readonly "audio_tokens"?: number
    readonly "reasoning_tokens"?: number
    readonly "text_tokens"?: number
    readonly "rejected_prediction_tokens"?: number
  }
  readonly "prompt_tokens_details"?: {
    readonly "audio_tokens"?: number
    readonly "cached_tokens"?: number
    readonly "text_tokens"?: number
    readonly "image_tokens"?: number
    readonly "cache_write_tokens"?: number
  }
}
export const CompletionUsage = Schema.Struct({
  "completion_tokens": Schema.Number.annotate({ "description": "Number of tokens in the generated completion." }).check(
    Schema.isInt().annotate({ "expected": "an integer" })
  ),
  "prompt_tokens": Schema.Number.annotate({ "description": "Number of tokens in the prompt." }).check(
    Schema.isInt().annotate({ "expected": "an integer" })
  ),
  "total_tokens": Schema.Number.annotate({
    "description": "Total number of tokens used in the request (prompt + completion)."
  }).check(Schema.isInt().annotate({ "expected": "an integer" })),
  "completion_tokens_details": Schema.optionalKey(
    Schema.Struct({
      "accepted_prediction_tokens": Schema.optionalKey(
        Schema.Number.annotate({
          "description":
            "When using Predicted Outputs, the number of tokens in the\nprediction that appeared in the completion.\n"
        }).check(Schema.isInt().annotate({ "expected": "an integer" }))
      ),
      "audio_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Audio input tokens generated by the model." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      ),
      "reasoning_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Tokens generated by the model for reasoning." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      ),
      "text_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Text output tokens generated by the model." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      ),
      "rejected_prediction_tokens": Schema.optionalKey(
        Schema.Number.annotate({
          "description":
            "When using Predicted Outputs, the number of tokens in the\nprediction that did not appear in the completion. However, like\nreasoning tokens, these tokens are still counted in the total\ncompletion tokens for purposes of billing, output, and context window\nlimits.\n"
        }).check(Schema.isInt().annotate({ "expected": "an integer" }))
      )
    }).annotate({ "description": "Breakdown of tokens used in a completion." })
  ),
  "prompt_tokens_details": Schema.optionalKey(
    Schema.Struct({
      "audio_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Audio input tokens present in the prompt." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      ),
      "cached_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Cached tokens present in the prompt." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      ),
      "text_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Text input tokens present in the prompt." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      ),
      "image_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "Image input tokens present in the prompt." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      ),
      "cache_write_tokens": Schema.optionalKey(
        Schema.Number.annotate({ "description": "The unadjusted number of prompt tokens written to cache." }).check(
          Schema.isInt().annotate({ "expected": "an integer" })
        )
      )
    }).annotate({ "description": "Breakdown of tokens used in the prompt." })
  )
}).annotate({ "description": "Usage statistics for the completion request.", "identifier": "CompletionUsage" })
