export type LiveDataChannelConfigParam = {
  readonly "allowed_client_events"?: "all" | ReadonlyArray<string>
  readonly "allowed_server_events"?: "all" | ReadonlyArray<LiveAllowedServerEventParam>
}
export const LiveDataChannelConfigParam = Schema.Struct({
  "allowed_client_events": Schema.optionalKey(
    Schema.Union([
      Schema.Literal("all"),
      Schema.Array(
        Schema.String.annotate({
          "description":
            "A Live client event type allowed on the frontend data channel, such as `session.input_audio.mute`."
        }).check(Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })).check(
          Schema.isMaxCodePoints(256).annotate({ "expected": "a string with at most 256 code points" })
        ).check(
          Schema.isPattern(new RegExp("^(?:error|info|[a-z][a-z0-9_-]*(?:\\.[a-z0-9_-]+)+)$", "u")).annotate({
            "expected": "a string matching the RegExp ^(?:error|info|[a-z][a-z0-9_-]*(?:\\.[a-z0-9_-]+)+)$"
          })
        )
      ).check(Schema.isMaxLength(256).annotate({ "expected": "a value with a length of at most 256" }))
    ], { mode: "oneOf" }).annotate({
      "description":
        "Client event types that the frontend data channel may send. Use 'all' to allow every client event; an empty array allows none. Omission preserves the existing allow-all behavior."
    })
  ),
  "allowed_server_events": Schema.optionalKey(
    Schema.Union([
      Schema.Literal("all"),
      Schema.Array(LiveAllowedServerEventParam).check(
        Schema.isMaxLength(256).annotate({ "expected": "a value with a length of at most 256" })
      )
    ], { mode: "oneOf" }).annotate({
      "description":
        "Server events that may be sent to the frontend data channel. Use 'all' to allow every server event; an empty array allows none. Omission preserves the existing allow-all behavior. Responses events use an object with type 'response.event' and a response_event selector."
    })
  )
}).annotate({
  "description":
    "Control which Live events an untrusted WebRTC frontend can send and receive over its data channel. These restrictions do not apply to trusted sideband connections.",
  "identifier": "LiveDataChannelConfigParam"
})
