export type BetaMCPTool = {
  readonly "type": "mcp"
  readonly "server_label": string
  readonly "server_url"?: string
  readonly "connector_id"?:
    | "connector_dropbox"
    | "connector_gmail"
    | "connector_googlecalendar"
    | "connector_googledrive"
    | "connector_microsoftteams"
    | "connector_outlookcalendar"
    | "connector_outlookemail"
    | "connector_sharepoint"
  readonly "tunnel_id"?: string
  readonly "authorization"?: string
  readonly "server_description"?: string
  readonly "headers"?: { readonly [x: string]: string } | null
  readonly "allowed_tools"?: ReadonlyArray<string> | BetaMCPToolFilter | null
  readonly "allowed_callers"?: ReadonlyArray<BetaCallableToolAllowedCaller> | null
  readonly "require_approval"?:
    | { readonly "always"?: BetaMCPToolFilter; readonly "never"?: BetaMCPToolFilter }
    | "always"
    | "never"
    | null
  readonly "defer_loading"?: boolean
}
export const BetaMCPTool = Schema.Struct({
  "type": Schema.Literal("mcp").annotate({ "description": "The type of the MCP tool. Always `mcp`." }),
  "server_label": Schema.String.annotate({
    "description": "A label for this MCP server, used to identify it in tool calls.\n"
  }),
  "server_url": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "The URL for the MCP server. One of `server_url`, `connector_id`, or\n`tunnel_id` must be provided.\n",
      "format": "uri"
    })
  ),
  "connector_id": Schema.optionalKey(
    Schema.Literals([
      "connector_dropbox",
      "connector_gmail",
      "connector_googlecalendar",
      "connector_googledrive",
      "connector_microsoftteams",
      "connector_outlookcalendar",
      "connector_outlookemail",
      "connector_sharepoint"
    ]).annotate({
      "description":
        "Identifier for service connectors, like those available in ChatGPT. One of\n`server_url`, `connector_id`, or `tunnel_id` must be provided. Learn more\nabout service connectors [here](https://developers.openai.com/api/docs/guides/tools-connectors-mcp#connectors).\n\nThis field is deprecated for models released after September 1, 2026.\nUse `server_url` to connect to a remote MCP server, or `tunnel_id` to\nconnect through a Secure MCP Tunnel.\n\nCurrently supported `connector_id` values are:\n\n- Dropbox: `connector_dropbox`\n- Gmail: `connector_gmail`\n- Google Calendar: `connector_googlecalendar`\n- Google Drive: `connector_googledrive`\n- Microsoft Teams: `connector_microsoftteams`\n- Outlook Calendar: `connector_outlookcalendar`\n- Outlook Email: `connector_outlookemail`\n- SharePoint: `connector_sharepoint`\n"
    })
  ),
  "tunnel_id": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "The Secure MCP Tunnel ID to use instead of a direct server URL. One of\n`server_url`, `connector_id`, or `tunnel_id` must be provided.\n"
    }).check(
      Schema.isPattern(new RegExp("^tunnel_[a-z0-9]{32}$", "u")).annotate({
        "expected": "a string matching the RegExp ^tunnel_[a-z0-9]{32}$"
      })
    )
  ),
  "authorization": Schema.optionalKey(
    Schema.String.annotate({
      "description":
        "An OAuth access token that can be used with a remote MCP server, either\nwith a custom MCP server URL or a service connector. Your application\nmust handle the OAuth authorization flow and provide the token here.\n"
    })
  ),
  "server_description": Schema.optionalKey(
    Schema.String.annotate({ "description": "Optional description of the MCP server, used to provide more context.\n" })
  ),
  "headers": Schema.optionalKey(
    Schema.Union([
      Schema.Record(Schema.String, Schema.String).annotate({
        "description": "Optional HTTP headers to send to the MCP server. Use for authentication\nor other purposes.\n"
      }),
      Schema.Null
    ])
  ),
  "allowed_tools": Schema.optionalKey(
    Schema.Union([
      Schema.Union([
        Schema.Array(Schema.String).annotate({
          "title": "MCP allowed tools",
          "description": "A string array of allowed tool names"
        }),
        BetaMCPToolFilter
      ], { mode: "oneOf" }).annotate({ "description": "List of allowed tool names or a filter object.\n" }),
      Schema.Null
    ])
  ),
  "allowed_callers": Schema.optionalKey(
    Schema.Union([
      Schema.Array(BetaCallableToolAllowedCaller).annotate({ "description": "The tool invocation context(s)." }).check(
        Schema.isMinLength(1).annotate({ "expected": "a value with a length of at least 1" })
      ),
      Schema.Null
    ])
  ),
  "require_approval": Schema.optionalKey(
    Schema.Union([
      Schema.Union([
        Schema.Struct({
          "always": Schema.optionalKey(BetaMCPToolFilter),
          "never": Schema.optionalKey(BetaMCPToolFilter)
        }).annotate({
          "title": "MCP tool approval filter",
          "description":
            "Specify which of the MCP server's tools require approval. Can be\n`always`, `never`, or a filter object associated with tools\nthat require approval.\n"
        }),
        Schema.Literals(["always", "never"]).annotate({
          "title": "MCP tool approval setting",
          "description":
            "Specify a single approval policy for all tools. One of `always` or\n`never`. When set to `always`, all tools will require approval. When\nset to `never`, all tools will not require approval.\n"
        })
      ], { mode: "oneOf" }).annotate({ "description": "Specify which of the MCP server's tools require approval." }),
      Schema.Null
    ])
  ),
  "defer_loading": Schema.optionalKey(
    Schema.Boolean.annotate({ "description": "Whether this MCP tool is deferred and discovered via tool search.\n" })
  )
}).annotate({
  "title": "MCP tool",
  "description":
    "Give the model access to additional tools via remote Model Context Protocol\n(MCP) servers. [Learn more about MCP](https://developers.openai.com/api/docs/guides/tools-connectors-mcp).\n",
  "identifier": "BetaMCPTool"
})
