export type Message = {
  readonly "type": "message"
  readonly "id": string
  readonly "status": MessageStatus
  readonly "role": MessageRole
  readonly "content": ReadonlyArray<
    | InputTextContent
    | OutputTextContent
    | TextContent
    | SummaryTextContent
    | ReasoningTextContent
    | RefusalContent
    | InputImageContent
    | ComputerScreenshotContent
    | InputFileContent
  >
  readonly "phase"?: MessagePhase_2 | null
}
export const Message = Schema.Struct({
  "type": Schema.Literal("message").annotate({ "description": "The type of the message. Always set to `message`." }),
  "id": Schema.String.annotate({ "description": "The unique ID of the message." }),
  "status": Schema.suspend((): Schema.Codec<MessageStatus> => MessageStatus).annotate({
    "description":
      "The status of item. One of `in_progress`, `completed`, or `incomplete`. Populated when items are returned via API."
  }),
  "role": Schema.suspend((): Schema.Codec<MessageRole> => MessageRole).annotate({
    "description":
      "The role of the message. One of `unknown`, `user`, `assistant`, `system`, `critic`, `discriminator`, `developer`, or `tool`."
  }),
  "content": Schema.Array(
    Schema.Union([
      InputTextContent,
      OutputTextContent,
      TextContent,
      SummaryTextContent,
      ReasoningTextContent,
      RefusalContent,
      InputImageContent,
      ComputerScreenshotContent,
      InputFileContent
    ], { mode: "oneOf" }).annotate({ "description": "A content part that makes up an input or output item." })
  ).annotate({ "description": "The content of the message" }),
  "phase": Schema.optionalKey(
    Schema.Union([
      Schema.suspend((): Schema.Codec<MessagePhase_2> => MessagePhase_2).annotate({
        "description":
          "Labels an `assistant` message as intermediate commentary (`commentary`) or the final answer (`final_answer`). For models like `gpt-5.3-codex` and beyond, when sending follow-up requests, preserve and resend phase on all assistant messages — dropping it can degrade performance. Not used for user messages."
      }),
      Schema.Null
    ])
  )
}).annotate({ "title": "Message", "description": "A message to or from the model.", "identifier": "Message" })
